package ge.opensoft.openservice;
import static ge.opensoft.openservice.Values.*;
import static ge.opensoft.openservice.WorkflowSupport.*;
import static org.junit.jupiter.api.Assertions.*;
import java.util.*;
final class MigrationFetchAcceptance {
    static String endpoint(String id){return "/api/openservice/migrations/"+id+"/fetch-jobs";}
    static String create(WorkflowSupport h)throws Exception{return TransferAcceptance.result(h.json("POST",TransferAcceptance.API,TransferValidationAcceptance.basic(),auth("admin")),201).get("job_id").toString();}
    static String queue(WorkflowSupport h,String migration,String key)throws Exception{return TransferAcceptance.result(h.json("POST",endpoint(migration),map("key",key,"token",MigrationSource.TOKEN),auth("admin")),201).get("job_id").toString();}
    static Map<String,Object> work(WorkflowSupport h,String job)throws Exception{return TransferAcceptance.result(h.get("/api/openservice/operations/jobs/"+job,auth("admin")),200);}
    static void source(int count){MigrationSource.reset();var rows=new ArrayList<Map<String,Object>>();for(int i=1;i<=count;i++)rows.add(map("sys_id",MigrationSource.key(i),"short_description","Staged private data "+i,"state","1","priority","3"));MigrationSource.tables.put("incident",rows);}
    static void run(WorkflowSupport h)throws Exception{
        source(701);MigrationSource.tables.put("problem",List.of(map("sys_id",MigrationSource.key(1001),"short_description","Second phase one"),map("sys_id",MigrationSource.key(1002),"short_description","Second phase two")));h.account("FetchReader","reader");h.account("FetchAgent","agent");var plan=TransferValidationAcceptance.basic();object(plan.get("tables")).put("problem",TransferAcceptance.mapping("problem",map("short_description","short_description")));String migration=TransferAcceptance.result(h.json("POST",TransferAcceptance.API,plan,auth("admin")),201).get("job_id").toString(),key=id(),job=queue(h,migration,key);assertEquals(job,queue(h,migration,key));assertEquals(0,MigrationSource.queries.size());
        assertEquals(409,h.json("POST",endpoint(migration),map("key",key,"token","different-token"),auth("admin")).statusCode());
        try(var db=h.store.open()){String encrypted=db.one("SELECT envelope FROM os_work WHERE job_id=?",job).get("envelope").toString();assertFalse(encrypted.contains(MigrationSource.TOKEN));assertEquals(MigrationSource.TOKEN,Outbox.decrypt(h.store.secret,encrypted).get("token"));}
        long now=System.currentTimeMillis()+100;var worker=new WorkWorker(h.store);assertTrue(worker.runOne(now));assertEquals("queued",work(h,job).get("state"));assertEquals(0,work(h,job).get("attempts"));assertEquals("fetching",object(work(h,job).get("receipt")).get("status"));assertEquals(100,object(work(h,job).get("receipt")).get("staged_rows"));assertEquals("continued",objects(WorkAttemptsAcceptance.history(h,job,"").get("result")).getFirst().get("state"));
        MigrationSource.status=503;assertTrue(worker.runOne(now+2000));assertEquals("retry_scheduled",objects(WorkAttemptsAcceptance.history(h,job,"").get("result")).getFirst().get("state"));try(var db=h.store.open()){assertEquals(100,db.count("SELECT COUNT(*) FROM os_transfer_item WHERE job_id=?",migration));assertEquals(MigrationSource.key(100),object(TransferJobs.job(db,migration).get("detail")).get("cursor"));}
        MigrationSource.status=200;worker=new WorkWorker(new Store(h.environment));int runs=0;while(!work(h,job).get("state").equals("succeeded")){assertTrue(++runs<=12);assertTrue(worker.runOne(now+20000L*runs));}
        assertTrue(runs>5);var completed=work(h,job);assertEquals("succeeded",completed.get("state"));assertEquals("review",object(completed.get("receipt")).get("status"));assertEquals(703,object(completed.get("receipt")).get("staged_rows"));assertEquals(2,object(completed.get("receipt")).get("phase"));String exposed=JSON.writeValueAsString(completed);assertFalse(exposed.contains(MigrationSource.TOKEN));assertFalse(exposed.contains("Staged private data"));assertFalse(object(completed.get("receipt")).containsKey("continue"));assertEquals(job,queue(h,migration,key));
        try(var db=h.store.open()){assertEquals("",db.one("SELECT envelope FROM os_work WHERE job_id=?",job).get("envelope"));assertEquals(703,db.count("SELECT COUNT(*) FROM os_transfer_item WHERE job_id=?",migration));assertEquals(2,db.count("SELECT COUNT(*) FROM os_transfer_item WHERE job_id=? AND source_table='problem'",migration));assertEquals(0,db.count("SELECT COUNT(*) FROM os_record WHERE sys_id=?",MigrationSource.key(701)));assertEquals("review",object(TransferJobs.job(db,migration).get("detail")).get("status"));}
        assertEquals(409,h.json("POST",endpoint(migration),map("key",id(),"token",MigrationSource.TOKEN),auth("admin")).statusCode());assertEquals(1,WorkSearchAcceptance.result(h,"?kind=migration.fetch").get("total"));
        for(Object bad:List.of(map(),map("key",id(),"token","bad token"),map("key",id(),"token","") ,map("key",id(),"token",MigrationSource.TOKEN,"extra","x")))assertEquals(400,h.json("POST",endpoint(migration),bad,auth("admin")).statusCode());
        for(var payload:List.of(map(),map("migration_id","bad","token",MigrationSource.TOKEN)))assertEquals(400,h.json("POST","/api/openservice/operations/jobs",map("kind","migration.fetch","key",id(),"payload",payload),auth("admin")).statusCode());
        assertEquals(404,h.json("POST",endpoint(id()),map("key",id(),"token",MigrationSource.TOKEN),auth("admin")).statusCode());assertEquals(405,h.get(endpoint(migration),auth("admin")).statusCode());assertEquals(400,h.json("POST",endpoint(migration)+"?x=y",map("key",id(),"token",MigrationSource.TOKEN),auth("admin")).statusCode());assertEquals(401,h.json("POST",endpoint(migration),map(),null).statusCode());for(String user:List.of("FetchReader","FetchAgent"))assertEquals(403,h.json("POST",endpoint(migration),map(),auth(user)).statusCode());
        String ui="/admin/migrations/"+migration+"/fetch";assertEquals(200,h.get(ui,auth("admin")).statusCode());assertFalse(html(h.get(ui,auth("admin"))).contains("name=\"token\""));assertEquals(404,h.get(ui.replace(migration,id()),auth("admin")).statusCode());assertEquals(400,h.get(ui+"?x=y",auth("admin")).statusCode());assertEquals(403,h.get(ui,auth("FetchAgent")).statusCode());
        String pending=create(h),formPath="/admin/migrations/"+pending+"/fetch";assertTrue(html(h.get(formPath,auth("admin"))).contains("background worker is disabled"));assertEquals(403,h.form(formPath,map("key",id(),"token",MigrationSource.TOKEN),auth("admin")).statusCode());assertEquals(302,h.protectedForm(formPath,map("key",id(),"token",MigrationSource.TOKEN),auth("admin")).statusCode());
        MigrationSource.reset();
    }
    static void boundaries(WorkflowSupport h)throws Exception{
        source(2);long now=System.currentTimeMillis()+100;var worker=new WorkWorker(h.store);
        String migration=create(h),first=queue(h,migration,id()),second=queue(h,migration,id());int ticks=0;while(!work(h,first).get("state").equals("succeeded") || !work(h,second).get("state").equals("succeeded")){assertTrue(++ticks<8);assertTrue(worker.runOne(now+10000L*ticks));}assertEquals(2,MigrationSource.queries.size());
        String stopped=create(h),stopWork=queue(h,stopped,id());try(var db=h.store.open()){PlatformFoundationTest.bind(db);MigrationStops.cancel(db,stopped,map("reason","Stop background read"));db.connection.commit();}int calls=MigrationSource.queries.size();assertTrue(worker.runOne(now+100000));assertEquals("cancelled",work(h,stopWork).get("state"));assertEquals(calls,MigrationSource.queries.size());try(var db=h.store.open()){assertEquals("",db.one("SELECT envelope FROM os_work WHERE job_id=?",stopWork).get("envelope"));}
        String revoked=create(h),revokedWork=queue(h,revoked,id());try(var db=h.store.open()){db.update("UPDATE os_work SET auth_revision=-1 WHERE job_id=?",revokedWork);db.connection.commit();}assertTrue(worker.runOne(now+200000));assertEquals("cancelled",work(h,revokedWork).get("state"));assertEquals(calls,MigrationSource.queries.size());
        String cancelled=create(h),cancelWork=queue(h,cancelled,id());assertEquals(200,h.json("POST","/api/openservice/operations/jobs/"+cancelWork,map("operation","cancel"),auth("admin")).statusCode());assertFalse(worker.runOne(now+300000));try(var db=h.store.open()){assertEquals("fetching",object(TransferJobs.job(db,cancelled).get("detail")).get("status"));assertEquals("",db.one("SELECT envelope FROM os_work WHERE job_id=?",cancelWork).get("envelope"));}
        String lease=create(h),leaseWork=queue(h,lease,id());Map<String,Object> old,current;try(var db=h.store.open()){old=WorkJobs.claim(db,now+400000);db.connection.commit();}try(var db=h.store.open()){current=WorkJobs.claim(db,now+600001);db.connection.commit();}assertTrue(worker.runClaimed(old,now+600002));assertEquals(calls,MigrationSource.queries.size());assertTrue(worker.runClaimed(current,now+600003));assertEquals(calls+1,MigrationSource.queries.size());assertEquals("queued",work(h,leaseWork).get("state"));
        // End the remaining page explicitly; a failed source never advances its checkpoint.
        MigrationSource.status=503;for(int i=1;i<=5;i++)assertTrue(worker.runOne(now+1000000L*i));assertEquals("failed",work(h,leaseWork).get("state"));try(var db=h.store.open()){assertEquals(MigrationSource.key(2),object(TransferJobs.job(db,lease).get("detail")).get("cursor"));assertEquals(2,db.count("SELECT COUNT(*) FROM os_transfer_item WHERE job_id=?",lease));}
        MigrationSource.status=200;assertEquals(200,h.json("POST","/api/openservice/operations/jobs/"+leaseWork,map("operation","retry"),auth("admin")).statusCode());assertTrue(new WorkWorker(new Store(h.environment)).runOne(now+7000000));assertEquals("succeeded",work(h,leaseWork).get("state"));MigrationSource.reset();
    }
}
